@import url('https://fonts.googleapis.com/css2?family=Source+Sans+3:wght@300;400;500;600&family=Spectral:wght@300;400;500&display=swap');

@font-face {
  font-family: 'Lyon Display Web';
  src:
    local('Lyon Display Web'),
    local('LyonDisplay-Light'),
    local('Lyon Display Light');
  font-style: normal;
  font-weight: 300;
  font-display: swap;
}

@font-face {
  font-family: 'Lyon Text Web';
  src:
    local('Lyon Text Web'),
    local('LyonText-Regular'),
    local('Lyon Text Regular');
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

@font-face {
  font-family: 'Whitney SSm';
  src:
    local('Whitney SSm Light'),
    local('Whitney SSm Book'),
    local('Whitney SSm'),
    local('Whitney SSm A'),
    local('Whitney SSm B');
  font-style: normal;
  font-weight: 300;
  font-display: swap;
}

@font-face {
  font-family: 'Whitney SSm';
  src:
    local('Whitney SSm Book'),
    local('Whitney SSm'),
    local('Whitney SSm A'),
    local('Whitney SSm B');
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

@font-face {
  font-family: 'Whitney SSm';
  src:
    local('Whitney SSm Medium'),
    local('Whitney SSm Semibold'),
    local('Whitney SSm Bold');
  font-style: normal;
  font-weight: 600;
  font-display: swap;
}

:root {
  --font-body: 'Whitney SSm', 'Source Sans 3', 'Segoe UI', Arial, sans-serif;
  --font-heading: 'Lyon Display Web', 'Lyon Text Web', 'Spectral', 'Times New Roman', serif;
  --font-ui: 'Whitney SSm', 'Source Sans 3', 'Segoe UI', Arial, sans-serif;
  /* Aman bg-primary/theme-color */
  --bg: #f3eee7;
  --panel: #ffffff;
  --ink: #1f2733;
  --muted: #607086;
  --line: #d8e0ea;
  --primary: #446084;
  --primary-strong: #334862;
  --accent: #d26e4b;
  --danger: #b20000;
  --success: #7a9c59;
  --layout-max-width: 1200px;
  --layout-max-wide-width: 1360px;
  --layout-max-footer-width: 1240px;
  --layout-gutter: 2.4rem;
  --layout-gutter-mobile: 1.1rem;
  --radius: 16px;
  --shadow: 0 16px 34px rgba(30, 49, 75, 0.1);
  font-family: var(--font-body);
  color: var(--ink);
  background: #f3eee7;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  background-color: var(--bg);
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.45;
  letter-spacing: 0.0571428571rem;
  color: #313131;
  max-width: 100%;
  overflow-x: hidden;
}

button,
input,
textarea,
select {
  font-family: var(--font-ui);
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--font-heading);
  font-weight: 400;
  letter-spacing: 0.0357142857rem;
}

body.mobile-menu-open {
  position: fixed;
  left: 0;
  right: 0;
  width: 100%;
  overflow: hidden;
}

html {
  font-size: 14px;
  scroll-behavior: auto;
  text-size-adjust: 100%;
  -webkit-text-size-adjust: 100%;
  -webkit-font-smoothing: antialiased;
  max-width: 100%;
  overflow-x: hidden;
}

@supports (overflow: clip) {
  html,
  body {
    overflow-x: clip;
  }
}

a {
  color: inherit;
}

ul {
  margin: 0;
  padding: 0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.site-shell {
  min-height: 100vh;
  min-height: 100svh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  position: relative;
  isolation: isolate;
  overflow-x: clip;
}

/* Keep homepage visual system untouched; apply Aman background to other public routes. */
.site-shell:not(.is-admin-route):not(.is-home-route):not(.has-global-video) {
  background: var(--bg);
}

.site-shell.has-global-video {
  background: #dbe6ef;
}

.site-shell.has-global-video .site-global-video-layer {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.site-shell.has-global-video .site-global-video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(1.06) contrast(1.02) brightness(1.16);
}

.site-shell.has-global-video .site-global-video-mask {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(249, 253, 255, 0.16) 0%, rgba(238, 246, 252, 0.24) 100%),
    radial-gradient(circle at 18% 20%, rgba(189, 223, 241, 0.16) 0%, rgba(189, 223, 241, 0) 42%);
}

.site-shell.has-global-video > :not(.site-global-video-layer):not(.topbar):not(
    .mobile-menu-overlay
  ):not(.language-popup-overlay):not(.home-anslife-search-popup-overlay) {
  position: relative;
  z-index: 1;
}

.site-shell.has-global-video .topbar {
  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.96) 0%,
      rgba(251, 254, 255, 0.94) 48%,
      rgba(248, 252, 255, 0.9) 100%
    );
  border-bottom-color: rgba(128, 152, 172, 0.2);
  box-shadow: 0 8px 20px rgba(34, 55, 78, 0.1);
}

.site-shell.has-global-video .topbar-utility {
  border-bottom-color: rgba(128, 152, 172, 0.2);
}

.site-shell.has-global-video .topbar-segment-link,
.site-shell.has-global-video .topbar-meta-link,
.site-shell.has-global-video .menu-link,
.site-shell.has-global-video .topbar-hotline,
.site-shell.has-global-video .brand,
.site-shell.has-global-video .language-switcher {
  color: #233a52;
}

.site-shell.has-global-video .topbar-hotline,
.site-shell.has-global-video .language-switcher,
.site-shell.has-global-video .social-link {
  border-color: rgba(128, 152, 172, 0.28);
  background: rgba(255, 255, 255, 0.84);
}

.site-shell.has-global-video .topbar-segment-link:hover,
.site-shell.has-global-video .topbar-segment-link.is-active,
.site-shell.has-global-video .topbar-meta-link:hover,
.site-shell.has-global-video .topbar-meta-link.is-active,
.site-shell.has-global-video .menu-link:hover,
.site-shell.has-global-video .menu-link.is-active {
  color: #103f26;
  background: rgba(164, 198, 56, 0.2);
}

.language-popup-overlay {
  position: fixed;
  inset: 0;
  z-index: 220;
  background: rgba(12, 21, 33, 0.56);
  backdrop-filter: blur(3px);
  display: grid;
  place-items: center;
  padding: 1rem;
}

.language-popup-card {
  width: min(560px, 100%);
  border-radius: 16px;
  border: 1px solid rgba(68, 96, 132, 0.22);
  background: linear-gradient(170deg, #fff 0%, #f6f8fc 100%);
  box-shadow: 0 20px 44px rgba(11, 23, 38, 0.26);
  padding: 1.2rem 1.1rem;
}

.language-popup-card h2 {
  margin: 0;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  color: #26374f;
}

.language-popup-card p {
  margin: 0.6rem 0 0;
  color: #4f6077;
  line-height: 1.55;
}

.language-popup-grid {
  margin-top: 0.9rem;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem;
}

.language-popup-option {
  border: 1px solid rgba(68, 96, 132, 0.22);
  background: #fff;
  border-radius: 12px;
  padding: 0.78rem 0.75rem;
  text-align: left;
  cursor: pointer;
  display: grid;
  gap: 0;
}

.language-popup-option strong {
  font-size: 0.95rem;
  color: #25364d;
}

.language-popup-option:hover {
  border-color: rgba(68, 96, 132, 0.42);
  background: rgba(68, 96, 132, 0.08);
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background:
    linear-gradient(
      180deg,
      rgba(238, 246, 255, 0.94) 0%,
      rgba(251, 253, 255, 0.98) 40%,
      rgba(255, 255, 255, 0.98) 100%
    );
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(68, 96, 132, 0.18);
  box-shadow: 0 10px 24px rgba(22, 35, 52, 0.09);
  overflow-anchor: none;
}

.topbar-inner {
  width: min(var(--layout-max-width), calc(100% - var(--layout-gutter)));
  margin: 0 auto;
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    'utility utility utility'
    'brand nav login'
    'subnav subnav subnav'
    'mobile mobile mobile';
  align-items: center;
  column-gap: 0.85rem;
  row-gap: 0.3rem;
  padding: 0.4rem 0 0.5rem;
}

.topbar-utility {
  grid-area: utility;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  min-height: 34px;
  border-bottom: 1px solid rgba(68, 96, 132, 0.15);
  padding-bottom: 0.26rem;
}

.topbar-segment-nav {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  flex-wrap: wrap;
}

.topbar-segment-link {
  text-decoration: none;
  color: #2a425d;
  font-size: 0.83rem;
  font-weight: 700;
  border-radius: 10px;
  padding: 0.3rem 0.72rem;
  transition: all 0.2s ease;
}

.topbar-segment-link:hover,
.topbar-segment-link.is-active {
  background: rgba(94, 140, 70, 0.16);
  color: #1b4a2a;
}

.topbar-segment-label {
  cursor: default;
}

.topbar-segment-label:hover {
  background: transparent;
  color: #2a425d;
}

.topbar-utility-right {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.52rem;
  min-width: 0;
}

.topbar-meta-nav {
  display: flex;
  align-items: center;
  gap: 0.2rem;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.topbar-meta-nav::-webkit-scrollbar {
  display: none;
}

.topbar-meta-link {
  position: relative;
  text-decoration: none;
  color: #2e455e;
  font-size: 0.81rem;
  font-weight: 600;
  padding: 0.22rem 0.5rem;
  border-radius: 8px;
  white-space: nowrap;
  transition: all 0.2s ease;
}

.topbar-meta-link:hover,
.topbar-meta-link.is-active {
  color: #183c59;
  background: rgba(68, 96, 132, 0.12);
}

.topbar-hotline {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  text-decoration: none;
  border: 1px solid rgba(68, 96, 132, 0.2);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.88);
  color: #233a52;
  font-size: 0.86rem;
  font-weight: 700;
  padding: 0.28rem 0.6rem;
  white-space: nowrap;
}

.topbar-hotline span:first-child {
  font-size: 0.82rem;
  line-height: 1;
}

.topbar-primary {
  display: contents;
}

.topbar-primary.is-admin-route {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 0.72rem;
  min-height: 64px;
}

.topbar-primary.is-admin-route .header-language {
  margin-left: auto;
}

.topbar-utility .language-switcher {
  width: 94px;
  max-width: none;
  font-size: 0.66rem;
  border-radius: 7px;
  padding: 0.34rem 1.15rem 0.34rem 0.5rem;
}

.brand {
  grid-area: brand;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0;
  white-space: nowrap;
}

.brand-logo {
  display: block;
  width: auto;
  height: 44px;
  object-fit: contain;
}

.mobile-home-menu-fab,
.mobile-home-language-fab,
.mobile-home-search-fab {
  border: 0;
  text-decoration: none;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  flex: 0 0 auto;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  pointer-events: auto;
  position: relative;
  z-index: 4202;
}

.mobile-home-menu-fab,
.mobile-home-language-fab,
.mobile-home-search-fab {
  display: none;
}

.mobile-home-actions {
  display: none;
  align-items: center;
  justify-content: flex-end;
  grid-auto-flow: column;
  grid-auto-columns: max-content;
  gap: 0.22rem;
  position: relative;
  z-index: 4203;
}

.mobile-home-menu-fab {
  width: 44px;
  height: 44px;
  background: transparent;
  color: #20384f;
  border: 0;
  box-shadow: none;
  font-size: 1.05rem;
  line-height: 1;
}

.mobile-home-language-fab {
  width: 44px;
  height: 44px;
  background: transparent;
  color: #20384f;
  border: 0;
  box-shadow: none;
  font-size: 1.05rem;
  line-height: 1;
}

.mobile-home-search-fab {
  width: 44px;
  height: 44px;
  background: transparent;
  color: #20384f;
  border: 0;
  box-shadow: none;
  font-size: 1.05rem;
  line-height: 1;
}

.mobile-home-menu-fab svg,
.mobile-home-language-fab svg,
.mobile-home-search-fab svg {
  width: 1.14rem;
  height: 1.14rem;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.mobile-home-language-fab.is-active {
  background: transparent;
  border-color: transparent;
  color: #1f3d59;
}

.mobile-home-search-fab.is-active {
  background: transparent;
  border-color: transparent;
  color: #1f3d59;
}

.home-mobile-language-menu {
  position: absolute;
  top: calc(100% + 0.28rem);
  right: 0;
  width: min(190px, calc(100vw - 1.2rem));
  border: 1px solid rgba(23, 40, 59, 0.12);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 12px 26px rgba(14, 28, 46, 0.22);
  backdrop-filter: blur(10px);
  overflow: hidden;
  z-index: 4300;
}

.home-mobile-language-option {
  width: 100%;
  min-height: 42px;
  border: 0;
  border-bottom: 1px solid rgba(23, 40, 59, 0.08);
  background: transparent;
  color: #17283b;
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr) 18px;
  align-items: center;
  gap: 0.48rem;
  padding: 0.44rem 0.58rem;
  text-align: left;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 650;
  cursor: pointer;
}

.home-mobile-language-option:last-child {
  border-bottom: 0;
}

.home-mobile-language-option:hover,
.home-mobile-language-option.is-active {
  background: rgba(68, 96, 132, 0.08);
}

.home-mobile-language-flag {
  width: 26px;
  height: 19px;
  display: grid;
  place-items: center;
  border-radius: 3px;
  background: rgba(23, 40, 59, 0.06);
  font-size: 0.9rem;
  line-height: 1;
  overflow: hidden;
}

.home-mobile-language-label {
  min-width: 0;
}

.home-mobile-language-check {
  color: #f07c35;
  font-size: 1rem;
  line-height: 1;
  justify-self: end;
}


.header-actions {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
}

.header-action-pill {
  display: inline-flex;
  align-items: center;
  text-decoration: none;
  border-radius: 999px;
  border: 1px solid rgba(68, 96, 132, 0.25);
  background: #fff;
  color: #2f4562;
  padding: 0.48rem 0.8rem;
  font-size: 1rem;
  font-weight: 700;
  white-space: nowrap;
  transition: all 0.2s ease;
}

.header-action-pill:hover {
  border-color: rgba(68, 96, 132, 0.45);
  background: rgba(68, 96, 132, 0.08);
}

.header-action-pill.primary {
  border-color: transparent;
  color: #fff;
  background: linear-gradient(120deg, #3f5c80 0%, #2f4765 100%);
}

.header-action-pill.primary:hover {
  background: linear-gradient(120deg, #355174 0%, #273f5d 100%);
}

.header-language {
  display: inline-flex;
  align-items: center;
}

.language-switcher {
  border: 1px solid rgba(68, 96, 132, 0.3);
  border-radius: 8px;
  background: #fff;
  color: #334862;
  font-weight: 700;
  font-size: 0.72rem;
  letter-spacing: 0.01em;
  padding: 0.48rem 1.5rem 0.48rem 0.62rem;
  cursor: pointer;
  width: 150px;
  max-width: 24vw;
}

.language-switcher:focus {
  outline: 2px solid rgba(68, 96, 132, 0.25);
}

.social-links {
  display: inline-flex;
  align-items: center;
  gap: 0.34rem;
}

.social-link {
  width: 32px;
  height: 32px;
  border-radius: 999px;
  border: 1px solid rgba(68, 96, 132, 0.25);
  background: #fff;
  color: #39506c;
  display: inline-grid;
  place-items: center;
  text-decoration: none;
  transition: all 0.2s ease;
}

.social-link svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
}

.social-link:hover {
  color: #fff;
  border-color: transparent;
  background: linear-gradient(120deg, #3f5c80 0%, #2f4765 100%);
  transform: translateY(-1px);
}

.site-shell.is-wood-theme-route .topbar {
  background: linear-gradient(180deg, #f5ebdc 0%, #efe2d0 100%);
  border-bottom-color: rgba(168, 130, 90, 0.24);
  box-shadow: 0 8px 18px rgba(58, 35, 18, 0.12);
  backdrop-filter: none;
}

.topbar.is-company-intro-theme {
  background: linear-gradient(180deg, #f5ebdc 0%, #efe2d0 100%);
  border-bottom-color: rgba(168, 130, 90, 0.24);
  box-shadow: 0 8px 18px rgba(58, 35, 18, 0.12);
  backdrop-filter: none;
}

.site-shell.is-wood-theme-route .topbar::before {
  content: none;
}

.site-shell.is-wood-theme-route .topbar-inner {
  width: min(var(--layout-max-wide-width), calc(100% - var(--layout-gutter)));
  position: relative;
  z-index: 1;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-areas:
    'utility utility utility'
    'brand nav login'
    'subnav subnav subnav'
    'mobile mobile mobile';
  row-gap: 0.28rem;
  column-gap: 0.6rem;
  padding: 0.28rem 0 0.34rem;
}

.site-shell.is-wood-theme-route .topbar-utility {
  display: flex;
  border-bottom-color: rgba(168, 130, 90, 0.2);
}

.site-shell.is-wood-theme-route .topbar-segment-link,
.site-shell.is-wood-theme-route .topbar-meta-link {
  color: #2e455e;
}

.site-shell.is-wood-theme-route .topbar-segment-link:hover,
.site-shell.is-wood-theme-route .topbar-segment-link.is-active,
.site-shell.is-wood-theme-route .topbar-meta-link:hover,
.site-shell.is-wood-theme-route .topbar-meta-link.is-active {
  color: #183c59;
  background: rgba(68, 96, 132, 0.12);
}

.site-shell.is-wood-theme-route .topbar-hotline {
  color: #233a52;
  border-color: rgba(68, 96, 132, 0.2);
  background: rgba(255, 255, 255, 0.88);
}

.site-shell.is-wood-theme-route .menu-link {
  color: #17283b;
  font-size: 0.88rem;
  border-radius: 0;
  padding: 0.46rem 0.66rem;
  font-weight: 750;
}

.site-shell.is-wood-theme-route .menu-link:hover {
  color: #16405e;
  background: rgba(68, 96, 132, 0.12);
}

.site-shell.is-wood-theme-route .menu-link.is-active {
  color: #233a52;
  background: rgba(68, 96, 132, 0.08);
}

.site-shell.is-wood-theme-route .menu-link.has-children::after {
  color: #6f8298;
}

.site-shell.is-wood-theme-route .brand-logo {
  height: 50px;
}

.site-shell.is-wood-theme-route .topbar-primary .header-language {
  grid-area: login;
  justify-self: end;
  align-self: center;
  margin-left: 0;
}

.site-shell.is-wood-theme-route .topbar-primary .language-switcher {
  width: 106px;
  border-radius: 8px;
  border: 1px solid rgba(68, 96, 132, 0.3);
  background: #fff;
  color: #334862;
  padding: 0.48rem 1.4rem 0.48rem 0.56rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  max-width: none;
}

.site-shell.is-wood-theme-route .topbar-primary .language-switcher:focus {
  outline-color: rgba(68, 96, 132, 0.25);
}

.site-shell.is-wood-theme-route .submenu,
.site-shell.is-wood-theme-route .submenu-flyout-panel {
  border-color: rgba(125, 84, 49, 0.36);
  background: #ffffff;
  box-shadow: 0 20px 36px rgba(43, 26, 14, 0.34);
}

.site-shell.is-wood-theme-route .submenu-link {
  border-color: rgba(131, 90, 52, 0.14);
  color: #54351b;
}

.site-shell.is-wood-theme-route .submenu-link:hover {
  background: #ffffff;
  border-color: rgba(131, 90, 52, 0.3);
  color: #3e2814;
}

.site-shell.is-wood-theme-route .submenu-link-arrow {
  color: #7f5733;
}

.site-shell.is-wood-theme-route .header-login-button {
  display: none;
}

.site-shell.is-wood-theme-route .main-nav {
