  gap: 0.9rem;
  margin-bottom: 0.95rem;
}

.home-ans-head h2 {
  margin: 0;
  font-size: 1.25rem;
  font-family: var(--font-heading);
  letter-spacing: 0.015em;
}

.home-ans-head a {
  width: fit-content;
}

.home-ans-category-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 0.46rem;
  margin-bottom: 0.85rem;
}

.home-ans-chip {
  border-radius: 999px;
  border: 1px solid rgba(68, 96, 132, 0.24);
  padding: 0.33rem 0.65rem;
  text-decoration: none;
  font-size: 0.82rem;
  color: var(--primary-strong);
  background: #fff;
}

.home-ans-chip:hover {
  background: rgba(68, 96, 132, 0.09);
}

.home-ans-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.8rem;
}

.home-ans-grid-compact {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.home-ans-card {
  display: grid;
  gap: 0.58rem;
  border-radius: 14px;
  border: 1px solid rgba(68, 96, 132, 0.16);
  background: linear-gradient(180deg, #fff 0%, #f8fafe 100%);
  padding: 0.8rem;
}

.home-ans-card img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: 10px;
}

.home-ans-tag {
  margin: 0;
