  gap: 0.65rem;
  flex-wrap: wrap;
}

.button-solid,
.button-ghost {
  text-decoration: none;
  border-radius: 999px;
  padding: 0.6rem 1rem;
  font-weight: 700;
  border: 1px solid transparent;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
}

.button-solid {
  background: linear-gradient(120deg, var(--primary) 0%, var(--primary-strong) 100%);
  color: #fff;
}

.button-solid:hover {
  transform: translateY(-1px);
}

.button-ghost {
  background: #fff;
  color: var(--primary-strong);
  border-color: rgba(68, 96, 132, 0.35);
