  background: var(--panel);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
}

.search-page-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.72rem;
  align-items: center;
}

.search-page-input-wrap {
  position: relative;
}

.search-page-input-icon {
  position: absolute;
  left: 0.72rem;
  top: 50%;
  transform: translateY(-50%);
  color: #5a7088;
  font-size: 1rem;
  line-height: 1;
  pointer-events: none;
}

.search-page-input {
  width: 100%;
  min-height: 46px;
  border-radius: 12px;
  border: 1px solid rgba(68, 96, 132, 0.24);
  background: #ffffff;
  color: #1f334a;
  font-size: 0.95rem;
  padding: 0.62rem 0.78rem 0.62rem 2.1rem;
