}

.search-page-submit {
  min-height: 46px;
  padding: 0.62rem 1.2rem;
}

.search-page-meta {
  margin: 0.74rem 0 0;
  color: #51667e;
  font-size: 0.9rem;
  line-height: 1.5;
}

.search-page-result-list {
  display: grid;
  gap: 0.62rem;
