.search-page-result-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.56rem;
  align-items: start;
  border: 1px solid rgba(68, 96, 132, 0.2);
  border-radius: 12px;
  background: #ffffff;
  padding: 0.72rem 0.78rem;
  text-decoration: none;
  transition:
    border-color 0.2s ease,
    background-color 0.2s ease;
