.search-page-result-item:hover {
  border-color: rgba(49, 88, 129, 0.42);
  background: #f8fbff;
}

.search-page-result-icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: 1px solid rgba(68, 96, 132, 0.18);
