.block-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.8rem;
  margin-bottom: 0.85rem;
}

.block-head h2,
.section-list h2,
.form-card h2 {
  margin: 0;
  font-family: var(--font-heading);
  letter-spacing: 0.05em;
}

/* Aman-inspired slim CTA link style */
.cta__link.card__link__cta.underline.single-link,
.home-ans-side-card a,
.home-ans-head a,
.block-head a,
.inline-link {
  position: relative;
  display: inline-block;
  color: #313131;
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 300;
  letter-spacing: 0.0571428571rem;
  line-height: 1.45;
  text-decoration: none;
  transition:
    color 0.2s ease,
    opacity 0.2s ease;
}

.cta__link.card__link__cta.underline.single-link::after,
.home-ans-side-card a::after,
.home-ans-head a::after,
.block-head a::after,
.inline-link::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  margin-top: 4px;
  border-bottom: 1px solid #7c7c7c;
