.ai-company-overview-card h3,
.ai-company-capability-card h3,
.ai-company-overview-info-card h2,
.ai-company-overview-section h2,
.ai-company-buyer-panel h2,
.ai-company-request-panel h2 {
  margin: 0;
  color: #24170f !important;
  font-family: var(--font-body);
  font-weight: 700;
  letter-spacing: 0;
}

.ai-company-overview-card h3,
.ai-company-capability-card h3 {
  font-size: 1.08rem;
  line-height: 1.28;
}

.ai-company-overview-card p,
.ai-company-capability-card p {
  margin: 0;
  color: #2d2018 !important;
  font-size: 0.92rem;
  line-height: 1.65;
}

.ai-company-overview-section {
  display: grid;
  gap: 0.85rem;
}

.ai-company-capability-grid {
  grid-template-columns: repeat(6, minmax(0, 1fr));
}

.ai-company-overview-action {
  display: flex;
  justify-content: center;
  margin-top: 0.45rem;
}

.ai-company-overview-action a,
.ai-company-request-primary,
.ai-company-request-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  min-height: 44px;
  border-radius: 6px;
  border: 1px solid #b88561;
  padding: 0 1.25rem;
  color: #9a5028 !important;
  font-weight: 700;
  text-decoration: none;
}

.ai-company-process {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 0.7rem;
  align-items: start;
}

.ai-company-process article {
  position: relative;
  display: grid;
  justify-items: center;
  gap: 0.45rem;
  text-align: center;
}

.ai-company-process article:not(:last-child)::after {
  content: '→';
  position: absolute;
  top: 39px;
  right: -0.58rem;
  color: #7a5a41;
  font-size: 1.25rem;
}

.ai-process-step {
  display: inline-grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border-radius: 999px;
  background: #111;
  color: #fff !important;
  font-size: 0.68rem;
  font-weight: 700;
  line-height: 1;
  z-index: 2;
}

.html-content .ai-content .ai-process-step {
  color: #fff !important;
}

.ai-process-icon {
  display: inline-grid;
  width: 56px;
  height: 56px;
  place-items: center;
  border: 1px solid #e4ded6;
  border-radius: 999px;
  background: var(--bg);
}

.ai-process-icon::before {
  width: 31px;
  height: 31px;
  background: #111;
}

.ai-mini-icon {
  display: inline-grid;
  width: 22px;
  height: 22px;
  place-items: center;
  flex: 0 0 auto;
}

.ai-mini-icon::before {
  content: '';
  display: block;
  width: 100%;
  height: 100%;
  background: #111;
  -webkit-mask: var(--ai-icon-mask) center / contain no-repeat;
  mask: var(--ai-icon-mask) center / contain no-repeat;
}

.ai-company-process strong {
  color: #2d2018 !important;
  font-size: 0.84rem;
  line-height: 1.42;
}

.ai-company-buyer-panel {
  display: grid;
  gap: 0.75rem;
  padding: 1rem;
}

.ai-company-buyer-points {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.8rem;
}

.ai-company-buyer-points span,
.ai-company-footer-strip span,
.ai-company-mini-icons span {
  position: relative;
  color: #2d2018 !important;
  font-size: 0.87rem;
  line-height: 1.42;
}

.ai-company-buyer-points span {
  padding-left: 1.8rem;
}

.ai-company-buyer-points span::before {
  content: '✓';
  position: absolute;
  left: 0;
  top: 0;
  display: inline-grid;
  width: 20px;
  height: 20px;
  place-items: center;
  border: 1px solid #c5906b;
  border-radius: 999px;
  color: #b85f2f;
  font-size: 0.75rem;
}

.ai-company-overview-info-grid {
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1.05fr) minmax(0, 0.95fr);
  align-items: start;
}

.ai-company-overview-info-card {
  padding: 1rem;
}

.ai-company-overview-info-card p {
  color: #2d2018 !important;
  font-size: 0.9rem;
  line-height: 1.58;
}

.ai-company-mini-icons {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  margin-top: 0.9rem;
  border-top: 1px solid #e8dfd4;
}

.ai-company-mini-icons span {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  align-items: center;
  justify-items: start;
  gap: 0.5rem;
  min-height: 52px;
  padding: 0.5rem 0.65rem;
  text-align: left;
}

.ai-company-mini-icons span:nth-child(even) {
  border-left: 1px solid #e8dfd4;
}

.ai-company-mini-icons span:nth-child(n + 3) {
  border-top: 1px solid #e8dfd4;
}

.ai-company-overview-table {
  margin: 0.75rem 0 0;
  display: grid;
  border-top: 1px solid #e8dfd4;
}

.ai-company-overview-table div {
  display: grid;
  grid-template-columns: minmax(110px, 0.42fr) minmax(0, 1fr);
  border-bottom: 1px solid #e8dfd4;
}

.ai-company-overview-table dt,
.ai-company-overview-table dd {
  margin: 0;
  padding: 0.42rem 0;
  color: #2d2018 !important;
  font-size: 0.86rem;
}

.ai-company-overview-table dt {
  font-weight: 700;
}

.ai-company-market-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.55rem;
  margin-top: 0.75rem;
}

.ai-company-market-grid span {
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 0.5rem;
  min-height: 86px;
  border: 1px solid #e8dfd4;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.32);
  padding: 0.65rem 0.45rem;
  color: #2d2018 !important;
  font-size: 0.86rem;
  text-align: center;
}

.ai-company-market-grid strong {
  color: #24170f !important;
  font-size: 0.9rem;
  line-height: 1.25;
}

.ai-company-market-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  margin: 0.75rem 0 0;
  border-top: 1px solid #e8dfd4;
  padding-top: 0.75rem;
  color: #2d2018 !important;
  font-size: 0.9rem;
  text-align: center;
}

.ai-company-market-note .ai-footer-icon {
  width: 20px;
  height: 20px;
}

.ai-market-flag {
  position: relative;
  display: inline-block;
  width: 42px;
  height: 28px;
  overflow: hidden;
  border: 1px solid #d8d0c6;
  border-radius: 4px;
  box-shadow: 0 5px 12px rgba(45, 32, 24, 0.08);
}

.ai-market-flag-jp {
  background: #f8f5ef;
}

.ai-market-flag-jp::after {
  content: '';
  position: absolute;
  inset: 8px 15px;
  border-radius: 999px;
  background: #c92645;
}

.ai-market-flag-us {
  background: repeating-linear-gradient(
    to bottom,
    #c92636 0 3px,
    #f8f5ef 3px 6px
  );
}

.ai-market-flag-us::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 18px;
  height: 15px;
  background: #24477f;
}

.ai-market-flag-eu {
  background: #174290;
}

.ai-market-flag-eu::after {
  content: '✦ ✦ ✦';
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #f1c84b;
  font-size: 0.45rem;
  letter-spacing: 0.08rem;
}

.ai-company-request-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 1rem;
  align-items: center;
  padding: 1rem;
  background: linear-gradient(90deg, var(--bg) 0%, #fff8ef 100%);
}

.ai-company-request-panel p {
  margin: 0.35rem 0 0;
  color: #2d2018 !important;
}

.ai-company-request-actions {
  display: flex;
  gap: 0.8rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.ai-company-request-primary {
  min-width: 180px;
  border-color: #df3f16;
  background: #df3f16;
  color: #fff !important;
}

.ai-company-request-secondary {
  min-width: 160px;
  background: transparent;
}

.ai-company-footer-strip {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0;
  border-top: 1px solid #e8dfd4;
  padding-top: 0.95rem;
}

.ai-company-footer-strip span {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  align-items: center;
  gap: 0.55rem;
  min-height: 44px;
  padding: 0 0.75rem;
  border-left: 1px solid #e8dfd4;
}

.ai-company-footer-strip span:first-child {
  border-left: 0;
  padding-left: 0;
}

.ai-finished-page {
  display: grid;
  gap: 1rem;
  border: 0;
  color: #2d2018;
  padding: 0;
  background: transparent;
  box-shadow: none;
}

.ai-finished-hero {
  position: relative;
  display: block;
  aspect-ratio: 1774 / 887;
  border: 0;
  border-radius: 0;
  min-height: clamp(360px, 34vw, 560px);
  background: url('/assets/products/finished-furniture-banner-ai.png') center center / cover
    no-repeat;
  overflow: hidden;
  isolation: isolate;
}

.ai-finished-hero-copy {
  position: absolute;
