/* Homepage one-screen mode (Vietcombank-inspired) */
.site-shell.is-home-route,
.site-shell:has(.home-anslife-root) {
  position: relative;
  height: 100vh;
  height: 100svh;
  height: 100dvh;
  min-height: 100svh;
  min-height: 100dvh;
  overflow: hidden;
}

.site-shell.is-home-route .content-shell,
.site-shell:has(.home-anslife-root) .content-shell {
  width: min(var(--layout-max-wide-width), calc(100% - var(--layout-gutter)));
  margin: 0 auto;
  flex: 1;
  min-height: 100svh;
  height: 100svh;
  min-height: 100dvh;
  height: 100dvh;
  overflow: hidden;
  display: block;
}

.home-anslife-root {
  --home-anslife-font: var(--font-ui);
  --home-anslife-green: #074c31;
  --home-anslife-lime: #a1c038;
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  height: 100svh;
  height: 100dvh;
  min-height: 100svh;
  min-height: 100dvh;
  z-index: 1;
}

.site-shell:not(.is-admin-route) .home-anslife-root :where(section, article, nav, aside, div, ul, li, form) {
  background: transparent !important;
}

.home-anslife-root .home-anslife-screen,
.home-anslife-root .home-anslife-screen * {
  font-family: var(--home-anslife-font);
}

.home-anslife-root .home-anslife-screen {
  --home-anslife-overlay-start: rgba(237, 248, 255, 0.04);
  --home-anslife-overlay-end: rgba(214, 233, 247, 0.12);
  --home-anslife-glow-color: rgba(255, 255, 255, 0.2);
  --home-anslife-screen-backdrop: linear-gradient(130deg, #95bbcf 0%, #a8cddd 45%, #c0dce8 100%);
  --home-anslife-media-filter: saturate(1.08) contrast(1.02) brightness(0.97);
  position: absolute;
  inset: 0;
  height: auto;
  min-height: 100svh;
  min-height: 100dvh;
  border-radius: 0;
  border: 0;
  box-shadow: none;
  overflow: hidden;
  padding: clamp(7rem, 11vh, 8.6rem) clamp(1rem, 2.1vw, 1.4rem)
    clamp(1rem, 2.1vw, 1.4rem);
  display: grid;
  grid-template-rows: 1fr auto;
  gap: clamp(0.7rem, 1.5vw, 0.95rem);
  background: var(--home-anslife-screen-backdrop) !important;
}

.home-anslife-root .home-anslife-screen.home-anslife-screen--light {
  --home-anslife-overlay-start: rgba(237, 248, 255, 0.03);
  --home-anslife-overlay-end: rgba(214, 233, 247, 0.1);
  --home-anslife-glow-color: rgba(255, 255, 255, 0.18);
  --home-anslife-screen-backdrop: linear-gradient(130deg, #95bbcf 0%, #a8cddd 45%, #c0dce8 100%);
  --home-anslife-media-filter: saturate(1.08) contrast(1.02) brightness(0.97);
}

.home-anslife-root .home-anslife-screen.home-anslife-screen--dark {
  --home-anslife-overlay-start: rgba(20, 35, 54, 0.34);
  --home-anslife-overlay-end: rgba(20, 35, 54, 0.48);
  --home-anslife-glow-color: rgba(166, 201, 229, 0.14);
  --home-anslife-screen-backdrop: linear-gradient(130deg, #52728f 0%, #5f80a3 45%, #7497ba 100%);
  --home-anslife-media-filter: saturate(1.05) contrast(1.04) brightness(0.82);
}

.home-anslife-screen-media {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.site-shell.has-global-video .home-anslife-screen-media {
  display: none;
}

.home-anslife-screen-media-picture {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.home-anslife-screen-media-picture img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.home-anslife-screen-media-fallback {
  position: absolute;
  inset: -3%;
  background-size: cover !important;
  background-position: center !important;
  filter: var(--home-anslife-media-filter);
  animation: home-anslife-pan-zoom 26s ease-in-out infinite alternate;
}

.home-anslife-screen-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: var(--home-anslife-media-filter);
}

@keyframes home-anslife-pan-zoom {
  0% {
    transform: scale(1.03) translate3d(-0.8%, -0.6%, 0);
  }

  100% {
    transform: scale(1.12) translate3d(1%, 0.8%, 0);
  }
}

.home-anslife-root .home-anslife-screen::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
