.ai-components-page {
  --component-paper: #f7f1e7;
  --component-ink: #252525;
  --component-muted: #5c5954;
  --component-line: rgba(37, 37, 37, 0.42);
  --component-soft-line: rgba(37, 37, 37, 0.12);
  display: grid;
  gap: 1rem;
  color: var(--component-ink);
  font-family: var(--font-body);
}

.ai-components-page,
.ai-components-page * {
  box-sizing: border-box;
}

.ai-components-hero,
.ai-components-catalog,
.ai-components-cta {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--component-soft-line);
  border-radius: 8px;
  background:
    repeating-linear-gradient(102deg, rgba(37, 37, 37, 0.035) 0 1px, transparent 1px 8px),
    radial-gradient(circle at 18% 12%, rgba(255, 255, 255, 0.72), transparent 34rem),
    var(--component-paper);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.55);
}

.ai-components-hero::before,
.ai-components-catalog::before,
.ai-components-cta::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(rgba(37, 37, 37, 0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(37, 37, 37, 0.025) 1px, transparent 1px);
  background-size: 28px 28px;
  mix-blend-mode: multiply;
}

.ai-components-hero {
  position: relative;
  display: block;
  aspect-ratio: 1798 / 875;
  min-height: clamp(360px, 34vw, 560px);
  overflow: hidden;
  border: 0;
  border-radius: 0;
  padding: 0;
  background: url('/assets/products/furniture-components/banner_ket_cau.webp') center center / cover
    no-repeat;
  box-shadow: none;
  isolation: isolate;
}

.ai-components-hero::before {
  content: '';
  position: absolute;
