.ai-component-upholstery-packaging-panel {
  overflow: hidden;
}

.ai-component-upholstery-packaging-diagram {
  position: relative;
  min-height: 260px;
  margin: 0;
}

.ai-component-upholstery-packaging-image {
  position: absolute;
  left: 50%;
  top: 12px;
  z-index: 1;
  width: 95% !important;
  height: 236px !important;
  max-width: none !important;
  object-fit: contain;
  object-position: center;
  pointer-events: none;
  transform: translateX(-50%);
}

.ai-component-upholstery-packaging-sketch {
  position: absolute;
  left: 18%;
  top: 24px;
  width: 54%;
  height: 128px;
  color: rgba(32, 32, 32, 0.82);
}

.ai-component-upholstery-packaging-sketch span,
.ai-component-upholstery-packaging-sketch span::before,
.ai-component-upholstery-packaging-sketch span::after {
  content: '';
  position: absolute;
  display: block;
  box-sizing: border-box;
  border-color: currentColor;
}

.ai-upholstery-pack-base {
  left: 12px;
  bottom: 15px;
  width: 112px;
  height: 42px;
  border: 2px solid currentColor;
  transform: skewY(-10deg);
  background:
    linear-gradient(90deg, currentColor 0 2px, transparent 2px 30px, currentColor 30px 32px, transparent 32px),
    rgba(255, 255, 255, 0.16);
}

.ai-upholstery-pack-cushion {
  left: 56px;
  top: 14px;
  width: 98px;
  height: 34px;
  border: 2px solid currentColor;
  border-radius: 6px;
  transform: skewY(-10deg);
  background: repeating-linear-gradient(168deg, rgba(32, 32, 32, 0.14) 0 1px, transparent 1px 7px);
}

.ai-upholstery-pack-cover {
  left: 34px;
  top: 0;
  width: 84px;
  height: 20px;
  border: 2px solid currentColor;
  transform: skewX(-22deg);
  opacity: 0.76;
}

.ai-upholstery-pack-hardware {
  right: 16px;
  top: 58px;
  width: 42px;
  height: 26px;
  border: 2px solid currentColor;
  border-radius: 4px;
  background:
    radial-gradient(circle, currentColor 0 2px, transparent 3px) 8px 8px / 14px 12px,
    rgba(255, 255, 255, 0.15);
}

.ai-upholstery-pack-carton {
  right: 24px;
  bottom: 12px;
  width: 58px;
  height: 42px;
  border: 2px solid currentColor;
  background:
    linear-gradient(90deg, transparent 47%, currentColor 49% 51%, transparent 53%),
    linear-gradient(transparent 47%, currentColor 49% 51%, transparent 53%);
  transform: skewY(-8deg);
}

.ai-upholstery-pack-label {
  position: absolute;
  z-index: 2;
  display: block;
  color: var(--component-detail-ink) !important;
  font-size: clamp(0.54rem, 0.58vw, 0.66rem);
  font-weight: 800;
  line-height: 1.18;
  white-space: nowrap;
}

.ai-upholstery-pack-label::after {
  content: '';
  position: absolute;
  height: 1px;
  background: rgba(32, 32, 32, 0.62);
}

.ai-upholstery-pack-label-cover {
  left: 0;
  top: 20px;
}

.ai-upholstery-pack-label-cover::after {
  left: 100%;
  top: 0.55rem;
  width: 34px;
}

.ai-upholstery-pack-label-frame {
  left: 0;
  top: 94px;
}

.ai-upholstery-pack-label-frame::after {
  left: 100%;
  top: 0.55rem;
  width: 54px;
}

.ai-upholstery-pack-label-cushion {
  right: 0;
  top: 24px;
}

.ai-upholstery-pack-label-cushion::after,
.ai-upholstery-pack-label-hardware::after,
.ai-upholstery-pack-label-part::after,
.ai-upholstery-pack-label-carton::after {
  right: 100%;
  top: 0.55rem;
  width: 42px;
}

.ai-upholstery-pack-label-hardware {
  right: 0;
  top: 86px;
}

.ai-upholstery-pack-label-part {
  right: 0;
  top: 154px;
}

.ai-upholstery-pack-label-carton {
  right: 0;
  top: 212px;
}

@media (max-width: 1180px) {
  .ai-component-upholstery-info-panels {
