@media (max-width: 460px) {
  .ai-component-table-product-grid {
    grid-template-columns: 1fr;
  }

  .ai-component-table-product-card {
    grid-template-rows: 124px auto 1fr;
  }

  .ai-component-cabinet-product-card {
    grid-template-rows: 104px auto auto;
  }

  .ai-component-cabinet-product-image {
    height: 100px;
    transform: none;
  }

  .ai-component-table-specs .ai-component-detail-material-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ai-component-cabinet-specs .ai-component-detail-material-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ai-component-table-packaging-grid {
    grid-template-columns: 1fr;
  }

  .ai-component-cabinet-packaging-grid {
    grid-template-columns: 1fr;
  }

  .ai-component-cabinet-packaging-card {
    grid-template-rows: 92px auto;
  }

  .ai-component-cabinet-buyer-list {
    grid-template-columns: 1fr;
  }

  .ai-component-bed-buyer-tags {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ai-component-detail-joints-items {
    --joint-sprite-scale: 0.84;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ai-component-detail-groups-grid {
    grid-template-columns: 1fr;
  }

  .ai-component-detail-material-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ai-component-detail-material-card:last-child {
    grid-column: 1 / -1;
    max-width: 9rem;
    justify-self: center;
  }

  .ai-component-detail-finish-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ai-component-detail-process-flow {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.9rem 0.6rem;
  }

  .ai-component-detail-process-step {
    width: 100%;
  }

  .ai-component-detail-process-thumb {
    width: min(100%, 122px);
  }

  .ai-component-detail-process-image {
    width: min(100%, 122px);
  }

  .ai-component-detail-process-arrow {
    display: none;
  }
}

